"""Random strings to reverse: one line of ASCII.

Both parities are covered on purpose. An odd-length string has a middle
character that stays put, and a swap loop that runs one step too far will
undo itself there and look correct; an even-length one has no such cover.
"""

LETTERS = "abcdefghijklmnopqrstuvwxyz"
PUNCTUATION = ",.!?-'"


def generate(rng, count):
    builders = (_odd_length, _even_length, _palindrome, _with_spaces)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, text, description=""):
    return {"name": name, "stdin": text + "\n", "description": description}


def _letters(rng, length):
    return "".join(rng.choice(LETTERS) for _ in range(length))


def _odd_length(rng, index):
    return _case("odd length #%d" % index, _letters(rng, rng.choice([5, 7, 9, 11])),
                 "The middle character has nowhere to go.")


def _even_length(rng, index):
    return _case("even length #%d" % index, _letters(rng, rng.choice([4, 6, 8, 10])),
                 "No middle character to hide an off-by-one behind.")


def _palindrome(rng, index):
    half = _letters(rng, rng.randint(2, 5))
    middle = _letters(rng, 1) if rng.random() < 0.5 else ""
    return _case("already a palindrome #%d" % index, half + middle + half[::-1],
                 "Reversing this changes nothing -- which does not mean doing "
                 "nothing is correct.")


def _with_spaces(rng, index):
    words = [_letters(rng, rng.randint(2, 6)) for _ in range(rng.randint(2, 4))]
    return _case("spaces and punctuation #%d" % index,
                 " ".join(words) + rng.choice(PUNCTUATION),
                 "Every byte moves, spaces and punctuation included.")
